function makeChapter(id, title, short, subtitle, films, terms, pairs, authorNames) {
    return {
        id,
        title,
        short,
        subtitle,
        films,
        definitions: [["Définition simple", `${short} désigne une notion centrale du programme : elle doit toujours être définie avec ses sens possibles, ses limites et ses tensions.`], ["Définition philosophique", `Pour traiter ${short.toLowerCase()}, il faut éviter la définition trop rapide : la fiche met en relation vocabulaire, contradictions, auteurs, exemples et plans possibles.`]],
        terms,
        contradictions: pairs.map( ([a,b]) => [a, b, `La tension entre ${a} et ${b} permet de construire une problématique : l'un semble fournir une réponse évidente, mais l'autre oblige à la nuancer.`]),
        authors: authorNames.map( (name) => [name, referenceFor(name), ideaFor(name, short), "Citation exacte à vérifier dans l'édition avant de mettre entre guillemets ; sinon utiliser l'idée comme paraphrase fidèle.", exampleFor(short, films[0])]),
        amorces: films.map( (film) => [film, `Dans ${film}, une situation concrète permet d'introduire ${short.toLowerCase()} sans réciter le cours. En deux phrases, le film sert à poser une tension : ce qui semble évident au départ devient problématique dès qu'on analyse les choix, les contraintes ou les illusions des personnages.`]),
        subjects: subjectsFor(short)
    };
}

function referenceFor(name) {
    const refs = {
        "Descartes": "Discours de la méthode / Méditations métaphysiques",
        "Locke": "Essai sur l'entendement humain",
        "Freud": "Introduction à la psychanalyse",
        "Sartre": "L'existentialisme est un humanisme / L'Être et le Néant",
        "Bergson": "Essai sur les données immédiates de la conscience",
        "Nietzsche": "Le Gai Savoir / Généalogie de la morale",
        "Kant": "Fondements de la métaphysique des moeurs",
        "Rousseau": "Du contrat social",
        "Hobbes": "Léviathan",
        "Marx": "Le Capital / Manuscrits de 1844",
        "Rawls": "Théorie de la justice",
        "Pascal": "Pensées",
        "Popper": "La Logique de la découverte scientifique",
        "Bachelard": "La Formation de l'esprit scientifique",
        "Heidegger": "La Question de la technique",
        "Augustin": "Confessions"
    };
    return refs[name] || "Oeuvre de référence à préciser dans la fiche finale";
}

function ideaFor(name, topic) {
    return `${name} permet de penser ${topic.toLowerCase()} en dépassant l'opinion commune : son idée sert à construire un argument, pas seulement à décorer la copie.`;
}

function exampleFor(topic, film) {
    return `Exemple concret : utiliser ${film} ou une situation réelle pour montrer comment ${topic.toLowerCase()} devient un problème vécu, politique, moral ou existentiel.`;
}

function subjectsFor(topic) {
    return [[`${topic} nous rend-il plus libres ?`, ["On peut d'abord soutenir que oui, car la notion semble augmenter notre puissance d'agir.", "Mais elle peut aussi produire illusion, dépendance ou contrainte.", "Il faut donc distinguer une libération apparente et une liberté plus lucide."]], [`Peut-on se passer de ${topic.toLowerCase()} ?`, ["La notion peut sembler secondaire ou remplaçable.", "Pourtant elle répond à un besoin humain profond.", "On peut seulement en critiquer les formes dangereuses, pas l'abolir totalement."]], [`${topic} est-il toujours bénéfique ?`, ["Il apporte d'abord un avantage évident.", "Mais cet avantage peut avoir un prix moral, politique ou existentiel.", "Il devient bénéfique seulement sous certaines conditions."]], [`Faut-il limiter ${topic.toLowerCase()} ?`, ["Limiter semble d'abord empêcher ou appauvrir.", "Mais l'absence de limite peut produire des abus.", "La vraie question est de trouver une limite légitime, non arbitraire."]]];
}

const routes = [["accueil", "Accueil"], ...chapters.map( (c) => [c.id, c.title]), ["dissertation", "Méthode dissertation"], ["texte", "Méthode explication de texte"], ["contradictions", "Contradictions"], ["citations", "Citations"], ["lexique", "Lexique"]];

const app = document.getElementById("app");
const nav = document.getElementById("mainNav");
const searchInput = document.getElementById("searchInput");

function init() {
    nav.innerHTML = routes.map( ([id,label]) => `<a class="nav-link" href="#${id}" data-route="${id}">${label}</a>`).join("");
    nav.addEventListener("click", () => nav.classList.remove("open"));
    document.getElementById("menuToggle").addEventListener("click", () => nav.classList.toggle("open"));
    document.getElementById("topButton").addEventListener("click", () => window.scrollTo({
        top: 0,
        behavior: "smooth"
    }));
    window.addEventListener("hashchange", render);
    searchInput.addEventListener("input", renderSearch);
    render();
}

function currentRoute() {
    return (location.hash || "#accueil").replace("#", "");
}

function setActive(route) {
    document.querySelectorAll(".nav-link").forEach( (link) => link.classList.toggle("active", link.dataset.route === route));
}

function render() {
    const route = currentRoute();
    setActive(route);
    searchInput.value = "";
    const chapter = chapters.find( (c) => c.id === route);
    if (route === "accueil")
        app.innerHTML = homePage();
    else if (chapter)
        app.innerHTML = chapterPage(chapter);
    else if (route === "dissertation")
        app.innerHTML = dissertationPage();
    else if (route === "texte")
        app.innerHTML = textMethodPage();
    else if (route === "contradictions")
        app.innerHTML = contradictionsPage();
    else if (route === "citations")
        app.innerHTML = citationsPage();
    else if (route === "lexique")
        app.innerHTML = lexiquePage();
    else
        app.innerHTML = homePage();
    window.scrollTo({
        top: 0,
        behavior: "smooth"
    });
}

function homePage() {
    return `<section class="hero">
    <p class="eyebrow">Révisions Terminale Générale</p>
    <h1 class="hero-title">Bac Philo 2026</h1>
    <p class="hero-subtitle">Fiches, méthodes, contradictions, citations et lexique.</p>
    <p class="hero-note">Utilise la barre du haut pour ouvrir directement un chapitre ou une page méthode. Le site est pensé pour lire confortablement sur ordinateur comme sur téléphone.</p>
  </section>`;
}

function chapterPage(chapter) {
    const index = chapters.findIndex( (c) => c.id === chapter.id);
    const previous = chapters[(index - 1 + chapters.length) % chapters.length];
    const next = chapters[(index + 1) % chapters.length];
    return `<section>
    <div class="page-head">
      <div>
        <p class="eyebrow">${chapter.title}</p>
        <h1>${chapter.short}</h1>
        <p class="lead">${chapter.subtitle}</p>
      </div>
      <div class="card soft">
        <strong>Films</strong>
        <div class="pill-list">${chapter.films.map(pill).join("")}</div>
      </div>
    </div>
    <div class="grid two">
      ${chapter.definitions.map( ([title,text]) => `<article class="card"><h3>${title}</h3><p>${text}</p></article>`).join("")}
    </div>
    <article class="card wide">
      <h2>Vocabulaire lié au thème</h2>
      <div class="term-grid">${chapter.terms.map(termCard).join("")}</div>
    </article>
    <article class="card wide">
      <h2>Contradictions du chapitre</h2>
      <div class="grid two">${chapter.contradictions.map(contradictionCard).join("")}</div>
    </article>
    <article class="card wide">
      <h2>Auteurs, références, citations, exemples</h2>
      <div class="authors">${chapter.authors.map(authorBlock).join("")}</div>
    </article>
    <article class="card wide">
      <h2>Films et amorces courtes</h2>
      <div class="grid two">${chapter.amorces.map( ([film,text]) => `<div class="card soft"><h3>${film}</h3><p class="quote">${text}</p><p class="mini">À l'écrit : une phrase pour présenter la scène, une phrase pour relier au sujet, puis définition des termes.</p></div>`).join("")}</div>
    </article>
    <article class="card wide">
      <h2>Sujets possibles et plans</h2>
      <div class="plans">${chapter.subjects.map(subjectPlan).join("")}</div>
    </article>
    <div class="chapter-nav">
      <a class="action" href="#${previous.id}">← ${previous.short}</a>
      <a class="action" href="#${next.id}">${next.short} →</a>
    </div>
  </section>`;
}

function pill(text) {
    return `<span class="pill">${text}</span>`;
}

function termCard(term) {
    return `<div class="term"><b>${term}</b><p class="mini">${termDefs[term] || "Notion à définir dans le sujet : cherche son sens commun, son sens philosophique, son contraire et un exemple."}</p></div>`;
}

function contradictionCard([a,b,global]) {
    return `<div class="card soft">
    <h3>${a} / ${b}</h3>
    <p><strong>${a}</strong> : ${termDefs[a] || "premier terme de l'opposition, à définir précisément dans le sujet."}</p>
    <p><strong>${b}</strong> : ${termDefs[b] || "second terme de l'opposition, qui limite ou complique le premier."}</p>
    <p class="quote">${global}</p>
    <h4>Mini-plan</h4>
    <ol class="plan-list">
      <li>Le premier terme semble d'abord suffire.</li>
      <li>Le second terme révèle une limite ou une objection.</li>
      <li>Il faut dépasser l'opposition par une distinction plus précise.</li>
    </ol>
  </div>`;
}

function authorBlock([name,work,idea,quote,example]) {
    return `<div class="author-block">
    <h3>${name}</h3>
    <p><span class="status">Référence</span> <strong>${work}</strong></p>
    <h4>Idée détaillée</h4>
    <p>${idea}</p>
    <h4>Citation</h4>
    <p class="quote">${quote}</p>
    <h4>Exemple concret</h4>
    <p>${example}</p>
  </div>`;
}

function subjectPlan([subject,plan]) {
    return `<details>
    <summary>${subject}</summary>
    <ol class="plan-list">${plan.map( (line) => `<li>${line}</li>`).join("")}</ol>
  </details>`;
}

function dissertationPage() {
    return `<section class="method-section">
    <div class="page-head"><div><p class="eyebrow">Méthode</p><h1>Dissertation</h1><p class="lead">Analyser le sujet, formuler le problème, construire le plan, rédiger avec ADREC.</p></div></div>
    <article class="card"><h2>1. Analyse du sujet : les 7 passages</h2>
      <div class="grid two">
        <div><h3>Repérer l'implicite</h3><p>Le présupposé est ce que le sujet suppose sans le dire. Attention aux adverbes : toujours, seulement, nécessairement, vraiment.</p></div>
        <div><h3>Tous les sens</h3><p>Un mot peut avoir plusieurs sens. Il faut les distinguer, surtout avec liberté, bonheur, devoir, nature, vérité.</p></div>
        <div><h3>Pourquoi la question se pose</h3><p>Une bonne copie explique pourquoi la réponse n'est pas évidente.</p></div>
        <div><h3>Définir et confronter</h3><p>Cherche synonymes, antonymes, expressions courantes, puis fais apparaître une tension.</p></div>
      </div>
    </article>
    <article class="card"><h2>Formulations types de sujets</h2>${subjectFormsTable()}</article>
    <article class="card"><h2>2. Arguments et exemples</h2>
      <p><strong>Argument</strong> : idée générale qui justifie une thèse. Exemple : l'être humain a un libre arbitre car il peut être tenu responsable de ses actes.</p>
      <p><strong>Exemple</strong> : cas particulier qui illustre l'idée abstraite. Il doit être expliqué et relié au sujet.</p>
      <div class="steps">
        <div class="step"><b>Absurde</b><p>Si cette idée était vraie, elle mènerait à une conséquence impossible.</p></div>
        <div class="step"><b>Induction</b><p>On part de plusieurs cas pour dégager une idée générale.</p></div>
        <div class="step"><b>Déduction</b><p>On part d'un principe pour en tirer une conséquence.</p></div>
        <div class="step"><b>Alternative</b><p>On compare deux issues possibles.</p></div>
        <div class="step"><b>Analogie</b><p>On éclaire une idée par une situation comparable.</p></div>
      </div>
    </article>
    <article class="card"><h2>3. Problème et enjeux</h2>
      <p class="quote">Le problème n'est pas la question. Il apparaît quand deux réponses opposées semblent toutes les deux défendables.</p>
      <p>Formule : d'un côté, il est vrai que... mais de l'autre, il est aussi évident que...</p>
      <p>Les enjeux peuvent être existentiels, culturels, moraux, politiques ou liés à la connaissance.</p>
    </article>
    <article class="card"><h2>4. Plans types</h2>${plansTypes()}</article>
    <article class="card"><h2>5. Introduction</h2>
      <ol class="plan-list"><li>Annoncer le sujet naturellement.</li><li>Analyser un exemple problématique.</li><li>Définir les termes clés.</li><li>Montrer la contradiction.</li><li>Formuler le problème.</li><li>Annoncer le plan.</li></ol>
      <p class="quote">Dans The Truman Show, Truman semble vivre une existence heureuse, mais cette vie est entièrement fabriquée par d'autres. Le bonheur désigne une satisfaction durable, tandis que la liberté suppose la capacité de choisir sa propre vie. D'un côté, un individu peut ressentir du plaisir sans être libre ; mais de l'autre, un bonheur manipulé semble seulement apparent. Peut-on donc être heureux sans être libre ? Nous verrons d'abord que certains plaisirs existent sans liberté, puis que le bonheur authentique exige l'autonomie, avant de montrer que la liberté intérieure est une condition du bonheur humain.</p>
    </article>
    <article class="card"><h2>6. Développement : ADREC très détaillé</h2>${adrec()}</article>
    <article class="card"><h2>Transitions toutes faites</h2>
      <div class="grid two">${["Cependant, cette première réponse rencontre une limite.", "Toutefois, cette analyse ne suffit pas à résoudre le problème.", "Il faut donc dépasser cette opposition.", "La difficulté n'est donc pas de choisir simplement entre les deux thèses, mais de comprendre à quelles conditions elles peuvent être articulées."].map( (t) => `<p class="quote">${t}</p>`).join("")}</div>
    </article>
    <article class="card"><h2>7. Conclusion très détaillée</h2>
      <ol class="plan-list"><li><strong>Reformuler le problème</strong> : nous nous demandions si...</li><li><strong>Récapituler la progression</strong> : d'abord, ensuite, enfin.</li><li><strong>Réponse finale nette</strong> : on peut donc conclure que...</li><li><strong>Enjeu</strong> : moral, politique, culturel, existentiel ou théorique.</li></ol>
      <p class="quote">Nous nous demandions s'il est possible d'être heureux sans être libre. Nous avons d'abord montré que certains plaisirs peuvent exister dans une situation de contrainte. Cependant, nous avons ensuite vu qu'un bonheur manipulé reste fragile, car il ne permet pas à l'individu de se reconnaître comme auteur de sa vie. Enfin, il est apparu qu'un bonheur pleinement humain suppose au moins une liberté intérieure. On peut donc conclure qu'il est possible de ressentir du plaisir sans liberté, mais non d'atteindre un bonheur authentique sans autonomie. L'enjeu est politique : une société peut-elle prétendre rendre les individus heureux si elle les prive de choisir leur existence ?</p>
    </article>
  </section>`;
}

function subjectFormsTable() {
    const rows = [["Y a-t-il", "Existence ou possibilité", "Chercher ce qui existe vraiment ou peut exister."], ["Est-il", "Essence", "Définir ce qu'est la chose et ses limites."], ["Est-ce", "Identité, équivalence ou cause", "Tester si deux notions se recouvrent vraiment."], ["Peut-on", "Possibilité, capacité ou légitimité", "Distinguer possible en fait, en droit, moralement."], ["Suffit-il", "Condition nécessaire ou suffisante", "Montrer que X peut être nécessaire sans suffire."], ["Faut-il", "Obligation", "Demander si c'est nécessaire, moral ou souhaitable."], ["Pourquoi", "Cause, raison, objectif, sens", "Distinguer cause explicative et raison justificative."]];
    return `<div class="table-wrap"><table><tr><th>Formule</th><th>Ce que ça interroge</th><th>Réflexe</th></tr>${rows.map( (r) => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join("")}</table></div>`;
}

function plansTypes() {
    return `<div class="grid two">
    <div class="card soft"><h3>Question fermée</h3><p>I. En effet : réponse commune<br>II. Mais : critique<br>III. Donc : nouvelle solution</p></div>
    <div class="card soft"><h3>Suffit-il de X pour Y ?</h3><p>I. X est nécessaire<br>II. X n'est pas suffisant<br>III. Il faut une autre condition</p></div>
    <div class="card soft"><h3>Peut-on ?</h3><p>I. Possible en fait<br>II. Limite ou incapacité<br>III. Possible à certaines conditions</p></div>
    <div class="card soft"><h3>Fort présupposé</h3><p>I. Certes, on peut défendre le présupposé<br>II. Mais il doit être critiqué<br>III. Il faut le reformuler</p></div>
  </div>`;
}

function adrec() {
    const rows = [["A - Argument", "Pourquoi ?", "Idée générale qui répond au sujet. Elle doit être claire, défendable, plus générale qu'un exemple."], ["D - Développement", "C'est-à-dire ?", "On définit, on explique le lien logique, on montre pourquoi l'argument tient."], ["R - Référence", "Qui aide à penser ?", "Auteur + oeuvre + idée utile. La référence renforce l'argument, elle ne remplace pas l'explication."], ["E - Exemple", "Comment ?", "Cas concret précis : film, histoire, science, société, vie quotidienne. Il doit être relié au sujet."], ["C - Conclusion", "En quoi cela répond ?", "Retour explicite au sujet et préparation de la suite."]];
    return `<div class="steps">${rows.map( ([a,b,c]) => `<div class="step"><b>${a}</b><p><strong>${b}</strong></p><p>${c}</p></div>`).join("")}</div>
  <p class="quote">Exemple : On peut d'abord soutenir que la liberté est nécessaire au bonheur, car un individu privé de choix ne peut pas reconnaître sa vie comme la sienne. Être heureux ne signifie pas seulement éprouver du plaisir : cela suppose aussi d'adhérer à son existence. Rousseau permet d'éclairer cette idée lorsqu'il pense la liberté comme autonomie. Dans The Truman Show, Truman vit dans le confort, mais ses choix sont fabriqués. Ainsi, un bonheur sans liberté risque de n'être qu'un bonheur apparent.</p>`;
}

function textMethodPage() {
    return `<section class="method-section">
    <div class="page-head"><div><p class="eyebrow">Méthode</p><h1>Explication de texte</h1><p class="lead">Comprendre la thèse, suivre le raisonnement, expliquer sans paraphraser.</p></div></div>
    <article class="card"><h2>Objectif</h2><p>Il faut expliquer ce que l'auteur veut démontrer et comment il le démontre. Ce n'est ni un résumé, ni une dissertation déguisée.</p></article>
    <article class="card"><h2>Lecture active</h2><div class="steps"><div class="step"><b>Thème</b><p>De quoi parle le texte ? Quelle notion du programme ?</p></div><div class="step"><b>Thèse</b><p>Quelle idée principale l'auteur défend-il ?</p></div><div class="step"><b>Problème</b><p>À quelle difficulté le texte répond-il ?</p></div><div class="step"><b>Mouvements</b><p>Découpe en 2 ou 3 étapes logiques.</p></div><div class="step"><b>Connecteurs</b><p>Mais, donc, car, pourtant, ainsi : ils montrent la progression.</p></div></div></article>
    <article class="card"><h2>Introduction type</h2><p class="quote">Ce texte porte sur... Plus précisément, il pose le problème suivant :... L'auteur défend la thèse selon laquelle... Le texte progresse en trois mouvements : d'abord..., ensuite..., enfin...</p></article>
    <article class="card"><h2>Développement linéaire</h2><p>Pour chaque mouvement : citation courte, explication des mots, rôle dans le raisonnement, lien avec la thèse.</p><p class="quote">Lorsque l'auteur écrit \"...\", il ne veut pas simplement dire que... Cette expression montre que... Ce passage permet donc de...</p></article>
    <article class="card"><h2>Expliquer sans paraphraser</h2><div class="grid two"><div class="card soft"><h3>Paraphrase faible</h3><p>L'auteur dit que la liberté est importante.</p></div><div class="card soft"><h3>Explication forte</h3><p>L'auteur montre que la liberté ne peut pas être réduite au caprice, car une action impulsive peut nous rendre esclaves de nos désirs.</p></div></div></article>
    <article class="card"><h2>Conclusion</h2><p class="quote">Le texte répond donc au problème de savoir si... L'auteur défend l'idée que... Pour établir cette thèse, il a d'abord montré que..., puis..., enfin... L'enjeu du texte est alors...</p></article>
  </section>`;
}

function contradictionsPage() {
    return `<section>
    <div class="page-head"><div><p class="eyebrow">Boîte à problématiques</p><h1>Contradictions</h1><p class="lead">Chaque contradiction définit les deux termes, la tension globale, puis donne un sujet, une problématique et un mini-plan.</p></div></div>
    <div class="grid two">${generalContradictions.map( ([a,b]) => contradictionCard([a, b, `Si ${a} semble d'abord répondre au problème, ${b} révèle une limite. Cette opposition permet de construire un paradoxe et donc une problématique.`])).join("")}</div>
  </section>`;
}

function citationsPage() {
    return `<section>
    <div class="page-head"><div><p class="eyebrow">Sécurité citation</p><h1>Citations</h1><p class="lead">Une citation doit être exacte, comprise et expliquée. Si elle est incertaine, on utilise l'idée sans guillemets.</p></div></div>
    <article class="card"><h2>Banque de citations vérifiées ou signalées</h2><div class="table-wrap"><table><tr><th>Auteur</th><th>Oeuvre</th><th>Citation</th><th>Notion</th><th>Statut</th></tr>${citations.map( (c) => `<tr><td>${c[0]}</td><td>${c[1]}</td><td>${c[2]}</td><td>${c[3]}</td><td>${c[4]}</td></tr>`).join("")}</table></div></article>
    <article class="card"><h2>Comment utiliser une citation</h2><p class="quote">Cette citation permet de montrer que... Autrement dit... Dans le sujet, cela signifie que...</p></article>
  </section>`;
}

function lexiquePage() {
    const allTerms = Object.keys(termDefs).sort( (a, b) => a.localeCompare(b, "fr"));
    return `<section>
    <div class="page-head"><div><p class="eyebrow">Vocabulaire</p><h1>Lexique philosophique</h1><p class="lead">Définitions, distinctions et notions utiles pour construire les introductions et les problématiques.</p></div></div>
    <article class="card"><h2>Classement par thème</h2><div class="grid two">${Object.entries(lexiqueGroups).map( ([group,terms]) => `<div class="card soft"><h3>${group}</h3><div class="pill-list">${terms.map(pill).join("")}</div></div>`).join("")}</div></article>
    <article class="card"><h2>Distinctions à ne pas confondre</h2><div class="grid two">${distinctions.map( ([a,b,d]) => `<div class="card soft"><h3>${a} / ${b}</h3><p><strong>${a}</strong> : ${termDefs[a] || "à définir"}</p><p><strong>${b}</strong> : ${termDefs[b] || "à définir"}</p><p class="quote">${d}</p></div>`).join("")}</div></article>
    <article class="card"><h2>Définitions alphabétiques</h2><div class="term-grid">${allTerms.map(termCard).join("")}</div></article>
  </section>`;
}

function renderSearch() {
    const query = searchInput.value.trim().toLowerCase();
    if (!query)
        return render();
    setActive("");
    const chunks = [];
    for (const chapter of chapters) {
        const text = JSON.stringify(chapter).toLowerCase();
        if (text.includes(query))
            chunks.push(`<a class="card action" href="#${chapter.id}">${chapter.title}<br><span class="mini">${chapter.subtitle}</span></a>`);
    }
    for (const [term,definition] of Object.entries(termDefs)) {
        if ((term + " " + definition).toLowerCase().includes(query))
            chunks.push(`<div class="term"><b>${term}</b><p class="mini">${definition}</p></div>`);
    }
    for (const citation of citations) {
        if (citation.join(" ").toLowerCase().includes(query))
            chunks.push(`<div class="card soft"><h3>${citation[0]}</h3><p class="quote">${citation[2]}</p><p>${citation[1]} - ${citation[3]}</p></div>`);
    }
    app.innerHTML = `<section><div class="page-head"><div><p class="eyebrow">Recherche</p><h1>${query}</h1><p class="lead">${chunks.length} résultat(s)</p></div></div><div class="grid">${chunks.join("") || `<div class="empty card wide">Aucun résultat pour cette recherche.</div>`}</div></section>`;
}

init();
